    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.VehicleStartReadinessRecoverySupervisorSystem_Instance_vehicle_supervisor_process_request_priority_owner_postInit =>
        return (st"""// Begin test cases for VehicleStartReadinessRecoverySupervisorSystem_Instance_vehicle_supervisor_process_request_priority_owner_postInit
                    |
                    |test(s"VehicleStartReadinessRecoverySupervisorSystem_Instance_vehicle_supervisor_process_request_priority_owner_postInit: Check Post-condition$suffix") {
                    |  val postJson: String = st${tq}${postContainer.get}${tq}.render
                    |  val postContainer = scp_candidate.JSON.toVehicle_Start_Readiness_Recovery_SupervisorRequestPriorityOwner_vehicle_supervisor_process_request_priority_owner_PostState_Container_PS(postJson).left
                    |  assert(scp_candidate.Vehicle_Start_Readiness_Recovery_Supervisor.RequestPriorityOwner_vehicle_supervisor_process_request_priority_owner_GumboX.inititialize_IEP_Post_Container(postContainer))
                    |}
